const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"generatorId":"DG-500KVA-01","anomalySeverity":"NORMAL","fuelConsumptionLitersPerHour":28.4,"expectedBurnRateRange":"25 - 32 L/hr","theftOrLeakageRisk":"LOW","hoursRemainingToBCheck":42.5,"projectedBCheckDate":"2026-12-14","alerts":[],"maintenanceDirectives":["Check lube oil clarity and change primary fuel filter at 250h threshold","Inspect radiator coolant level and belt tension"]} } }];
}
